:root {
  --ink: #173b47;
  --water: #dceff1;
  --paper: #fffdf7;
  --line: #9cc9cd;
  --green: #24776d;
}

.launch-pass {
  box-sizing: border-box;
  width: 460px;
  padding: 16px;
  background: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 14px;
}

.pass-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}

.launch-pass h1 {
  margin: 0;
  color: var(--ink);
  font-size: 22px;
  line-height: 1;
}

.status {
  padding: 5px 8px;
  color: var(--paper);
  background: var(--green);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.8px;
}

.trip-details {
  display: flex;
  gap: 10px;
  padding: 11px 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.detail {
  flex: 1;
  margin: 0;
  color: var(--ink);
}

.label {
  display: block;
  margin-bottom: 3px;
  color: var(--green);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.8px;
}

.detail strong {
  font-size: 14px;
}

.pass-footer {
  display: flex;
  justify-content: space-between;
  padding-top: 10px;
  color: var(--ink);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.4px;
}
